using Microsoft.AspNetCore.Mvc; using MiniStore.Application.Dtos.Accounting; using MiniStore.Application.Services.Accounting; using MiniStore.Web.Authorization;
namespace MiniStore.Web.Controllers.Api.V1;
[ApiController, Route("api/v1/bank-statements")]
public sealed class BankStatementsApiController(BankStatementService service):ControllerBase
{ [HttpGet,PermissionAuthorize("BankStatements.View")] public Task<BankStatementWorkspaceDto> Get()=>service.GetAsync(); [HttpPost("accounts"),ValidateAntiForgeryToken,PermissionAuthorize("BankStatements.Import")] public Task<BankStatementWorkspaceDto> CreateAccount(CreateBankAccountDto dto)=>service.CreateAccountAsync(dto); [HttpPost("imports"),ValidateAntiForgeryToken,PermissionAuthorize("BankStatements.Import")] public async Task<BankStatementWorkspaceDto> Import([FromForm]int bankAccountId,[FromForm]IFormFile file){if(file is null)throw new ArgumentException("Choose a CSV file.");await using var s=file.OpenReadStream();using var ms=new MemoryStream();await s.CopyToAsync(ms);return await service.ImportAsync(bankAccountId,file.FileName,ms.ToArray());} }
